Theorem as_main_realizes_closed {HCEIL : HeapCeil} : forall H : asr,
  asan_rt_hyps H -> asan_driver_laws H -> afuzz_stmt H -> as_main_realizes_stmt H.
Proof.
  intros H HH DL AFZ. apply (as_main_realizes H HH DL).
  - exact (AsTargetRun.as_target_run H HH DL AFZ).
  - exact (adl_live H DL).
  - first [exact (atail_usage H HH DL) | exact (atail_usage H DL) | exact (atail_usage H HH)].
  - first [exact (atail_open H HH DL) | exact (atail_open H DL) | exact (atail_open H HH)].
  - first [exact (atail_rderr H HH DL) | exact (atail_rderr H DL) | exact (atail_rderr H HH)].
Qed.
